contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 burnValue) public {
        require(burnValue <= c.balanceOf(address(this)));

        uint256 beforeOwnerBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success;
        bool _success = c.burn(burnValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            success = _success;
            reverted = false;
        }
        assert(reverted || (success == true && c.balanceOf(address(this)) == beforeOwnerBalance - burnValue && c.totalSupply() == beforeTotalSupply - burnValue));
    }
}

