        vm.assume(burnValue <= c.balanceOf(address(this)));
        uint256 beforeOwnerBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeOwnerBalance = __r; } catch { return; }
        uint256 beforeTotalSupply;
        try c.totalSupply() returns (uint256 __r) { beforeTotalSupply = __r; } catch { return; }
        bool reverted;
        bool success;
        try c.burn(burnValue) returns (bool _success) {
            success = _success;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (success == true && c.balanceOf(address(this)) == beforeOwnerBalance - burnValue && c.totalSupply() == beforeTotalSupply - burnValue));
